@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .formLogin(form -> form
                .loginPage("/login")
                .loginProcessingUrl("/authenticate")  // POST endpoint for form submission
                .defaultSuccessUrl("/dashboard", true)
                .failureUrl("/login?error=true")
                .permitAll()
            );
        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService(UserRepository userRepo) {
        return username -> userRepo.findByEmail(username)
            .map(user -> User.builder()
                .username(user.getEmail())
                .password(user.getPasswordHash())  // Already BCrypt hashed
                .authorities(user.getRoles().toArray(new String[0]))
                .accountLocked(user.isLocked())
                .build()
            )
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();  // Used by DaoAuthenticationProvider
    }
}

@Configuration
@EnableWebSecurity
public class RestSecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())  // Disable for stateless REST API
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers("/api/**").authenticated()
            )
            .formLogin(form -> form
                .loginProcessingUrl("/api/auth/login")  // AJAX posts here
                .usernameParameter("email")  // Custom field name
                .passwordParameter("password")
                .successHandler((request, response, authentication) -> {
                    response.setContentType("application/json");
                    var user = (UserDetails) authentication.getPrincipal();
                    var body = Map.of(
                        "status", "success",
                        "username", user.getUsername(),
                        "authorities", user.getAuthorities().stream()
                            .map(GrantedAuthority::getAuthority)
                            .toList()
                    );
                    new ObjectMapper().writeValue(response.getWriter(), body);
                })
                .failureHandler((request, response, exception) -> {
                    response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                    response.setContentType("application/json");
                    var body = Map.of("status", "error", "message", exception.getMessage());
                    new ObjectMapper().writeValue(response.getWriter(), body);
                })
            );
        return http.build();
    }
}

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtTokenService jwtService;
    private final UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                    HttpServletResponse response, 
                                    FilterChain filterChain) throws ServletException, IOException {
        var authHeader = request.getHeader("Authorization");

        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            var token = authHeader.substring(7);
            var username = jwtService.extractUsername(token);

            if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
                var userDetails = userDetailsService.loadUserByUsername(username);

                if (jwtService.isTokenValid(token, userDetails)) {
                    // Create authenticated token manually (bypassing form login)
                    var authToken = new UsernamePasswordAuthenticationToken(
                        userDetails,                 // principal
                        null,                        // credentials (no password needed)
                        userDetails.getAuthorities() // authorities from UserDetails
                    );
                    authToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                    SecurityContextHolder.getContext().setAuthentication(authToken);
                }
            }
        }

        filterChain.doFilter(request, response);
    }
}

@Configuration
@EnableWebSecurity
public class SecureLoginConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .formLogin(form -> form
                .loginPage("/login")
                .failureHandler(authenticationFailureHandler())
                .permitAll()
            );
        return http.build();
    }

    @Bean
    public AuthenticationFailureHandler authenticationFailureHandler() {
        return (request, response, exception) -> {
            var errorMessage = "Invalid username or password";  // Generic message

            // Log specific exception server-side for debugging
            if (exception instanceof LockedException) {
                log.warn("Login attempt for locked account: {}", request.getParameter("username"));
                errorMessage = "Account is locked. Contact support.";
            } else if (exception instanceof DisabledException) {
                log.warn("Login attempt for disabled account: {}", request.getParameter("username"));
                errorMessage = "Account is disabled. Contact support.";
            } else if (exception instanceof BadCredentialsException) {
                // This covers both wrong password AND UsernameNotFoundException
                log.debug("Failed login attempt for: {}", request.getParameter("username"));
            }

            // For REST API, return JSON
            if (request.getHeader("Accept").contains("application/json")) {
                response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                response.setContentType("application/json");
                var body = Map.of("error", errorMessage);
                new ObjectMapper().writeValue(response.getWriter(), body);
            } else {
                // For web UI, redirect with error parameter
                response.sendRedirect("/login?error=true&message=" + URLEncoder.encode(errorMessage, StandardCharsets.UTF_8));
            }
        };
    }
}

@Configuration
@EnableWebSecurity
public class LogoutConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .logout(logout -> logout
                .logoutUrl("/api/auth/logout")  // POST endpoint for logout
                .logoutSuccessHandler(logoutSuccessHandler())
                .deleteCookies("JSESSIONID", "remember-me")  // Clean up cookies
                .invalidateHttpSession(true)  // Essential: invalidate session
                .clearAuthentication(true)
                .permitAll()
            )
            .rememberMe(remember -> remember
                .key("uniqueAndSecret")  // Must match for remember-me to work
                .tokenValiditySeconds(604800)  // 7 days
            );
        return http.build();
    }

    @Bean
    public LogoutSuccessHandler logoutSuccessHandler() {
        return (request, response, authentication) -> {
            if (authentication != null) {
                log.info("User logged out: {}", authentication.getName());
            }

            // Detect if client expects JSON (REST API) or redirect (web browser)
            var acceptHeader = request.getHeader("Accept");
            if (acceptHeader != null && acceptHeader.contains("application/json")) {
                response.setStatus(HttpServletResponse.SC_OK);
                response.setContentType("application/json");
                var body = Map.of("status", "success", "message", "Logged out successfully");
                new ObjectMapper().writeValue(response.getWriter(), body);
            } else {
                response.sendRedirect("/login?logout=true");
            }
        };
    }
}
